export default {
  async fetch(request) {
    return new Response("pg-proxy prototype: HTTP is only for health checks\n");
  },
  async connect(socket, env, ctx) {
    await socket.readable.pipeTo(socket.writable);
  },
};

const handler = {
  fetch: async () => new Response("ok"),
  connect: async (socket) => {
    const writer = socket.writable.getWriter();
    for await (const chunk of socket.readable) await writer.write(chunk);
  },
};
export default handler;

